<dialog id="detail"><h2 id="person"></h2><p id="house"></p><ul id="months" style="list-style:none;padding:0"></ul><p>Hubungi bendahara jika data tidak sesuai.</p><button id="close">Tutup</button></dialog>
<script>const modal=document.getElementById('detail');function show(el){const r=JSON.parse(el.dataset.row);document.getElementById('person').textContent=r.name;document.getElementById('house').textContent='Blok: '+r.house;const list=document.getElementById('months');list.replaceChildren();r.months.forEach((s,i)=>{const li=document.createElement('li');li.textContent=new Date(2026,i,1).toLocaleString('id',{month:'long'})+' — '+({paid:'LUNAS',unpaid:'BELUM BAYAR',partial:'SEBAGIAN',future:'BELUM JATUH TEMPO',exempt:'DIKECUALIKAN',unknown:'BELUM ADA DATA'}[s]);list.append(li)});modal.showModal()}document.querySelectorAll('[data-row]').forEach(e=>{e.addEventListener('click',()=>show(e));e.addEventListener('keydown',k=>{if(k.key==='Enter')show(e)})});document.getElementById('close').addEventListener('click',()=>modal.close());</script></body></html>
